%%\ INTERPOLACION 2D DE TERRENO: diezmado, reconstruccion y metricas
% MA-1006 - Grupo G05
%
% Idea: tomar el terreno completo (verdad), quedarse con 1 de cada k puntos
% en cada direccion, reconstruir los puntos quitados con distintos metodos
% y medir el error contra el terreno real SOLO en los puntos quitados.
%
% Requiere MATLAB R2016b o posterior (funciones locales al final del script).

clear; clc; close all;

%%\ ===================== CONFIGURACION =====================
fuente     = 'dem';   % 'sintetico'  o  'dem'
archivoDEM = 'arenal.tif';     % solo se usa si fuente = 'dem' (.asc o .tif)
nMax       = 301;           % tamano maximo (puntos por lado) al cargar un DEM
k          = 5;             % factor de diezmado: se conserva 1 de cada k puntos por direccion

%%\ ===================== 1) TERRENO REAL COMPLETO =====================
[x, y, Z] = cargarTerreno(fuente, archivoDEM, nMax);

% Recortar para que el ultimo punto de la malla quede entre los conservados
nx = 1 + k*floor((numel(x)-1)/k);
ny = 1 + k*floor((numel(y)-1)/k);
x = x(1:nx);  y = y(1:ny);  Z = Z(1:ny, 1:nx);
[X, Y] = meshgrid(x, y);

fprintf('Terreno real: %d x %d puntos | elevacion %.1f a %.1f m\n', ny, nx, min(Z(:)), max(Z(:))); %[output:9a870d20]

%%\ ===================== 2) TERRENO INCOMPLETO =====================
cols = 1:k:nx;
rows = 1:k:ny;
xc = x(cols);  yc = y(rows);
Zc = Z(rows, cols);                 % datos conservados (malla gruesa)
[Xc, Yc] = meshgrid(xc, yc);

mascara = true(size(Z));            % true = punto QUITADO (hay que predecirlo)
mascara(rows, cols) = false;

fprintf('Puntos conservados: %d de %d (%.1f%%). A predecir: %d\n', ... %[output:group:51e9d540] %[output:0e740c52]
    numel(Zc), numel(Z), 100*numel(Zc)/numel(Z), nnz(mascara)); %[output:group:51e9d540] %[output:0e740c52]

if numel(xc) < 4 || numel(yc) < 4
    error('Con k = %d la malla gruesa queda de %d x %d nodos. Reduzcan k.', k, numel(xc), numel(yc));
end

%%\ ===================== 3) METODOS DE INTERPOLACION =====================
% Cada metodo recibe los ejes de la malla completa (x, y) y devuelve una
% matriz de tamano ny x nx.
metodos = {
    'Bilineal',    @() interpBilineal(xc, yc, Zc, x, y)
    'Lagrange p3', @() interpLagrangeLocal(xc, yc, Zc, x, y, 3)
    'Spline',      @() interp2(xc, yc, Zc, X, Y, 'spline')   % referencia (funcion de MATLAB)
};

nM = size(metodos, 1);
pred = cell(nM, 1);
res  = repmat(struct('MAE',0,'RMSE',0,'Emax',0,'R2',0,'t',0), nM, 1);

for m = 1:nM
    tic;
    pred{m} = metodos{m,2}();
    t = toc;
    res(m) = metricas(Z, pred{m}, mascara);
    res(m).t = t;
end

% Verificacion de la bilineal propia contra interp2 'linear'
Zlin = interp2(xc, yc, Zc, X, Y, 'linear');
fprintf('Chequeo bilineal propia vs interp2(linear): diferencia maxima = %.2e\n', ... %[output:group:5b81d79d] %[output:04a26419]
    max(abs(pred{1}(:) - Zlin(:)))); %[output:group:5b81d79d] %[output:04a26419]

%%\ ===================== 4) TABLA DE RESULTADOS =====================
fprintf('\nMetricas sobre los puntos quitados (m):\n'); %[output:2bcd1f53]
fprintf('%-14s %9s %9s %9s %8s %10s\n', 'Metodo', 'MAE', 'RMSE', 'Error max', 'R2', 'Tiempo(s)'); %[output:0cb0718b]
for m = 1:nM %[output:group:2cf7792d]
    fprintf('%-14s %9.3f %9.3f %9.3f %8.5f %10.4f\n', metodos{m,1}, ... %[output:900e399a]
        res(m).MAE, res(m).RMSE, res(m).Emax, res(m).R2, res(m).t); %[output:900e399a]
end %[output:group:2cf7792d]

%%\ ===================== 5) GRAFICAS: TERRENOS =====================
cmap = terrain_like();
zl = [min(Z(:)) max(Z(:))];

figure('Name', 'Terrenos', 'Position', [50 50 1400 800]); %[output:2e6f0a40]

subplot(2,3,1); %[output:2e6f0a40]
scatter3(Xc(:), Yc(:), Zc(:), 14, Zc(:), 'filled'); %[output:2e6f0a40]
colormap(gca, cmap); caxis(zl); axis tight; view(35, 45); %[output:2e6f0a40]
title(sprintf('Incompleto (1 de cada %d puntos)', k)); %[output:2e6f0a40]
xlabel('x'); ylabel('y'); zlabel('Elevacion (m)'); %[output:2e6f0a40]

subplot(2,3,2); %[output:2e6f0a40]
mostrarSuperficie(X, Y, Z, 'Real completo', cmap, zl); %[output:2e6f0a40]

for m = 1:nM
    subplot(2,3,2+m); %[output:2e6f0a40]
    mostrarSuperficie(X, Y, pred{m}, ...
        sprintf('%s\nRMSE = %.2f m | R^2 = %.4f', metodos{m,1}, res(m).RMSE, res(m).R2), ...
        cmap, zl);
end

subplot(2,3,6); %[output:2e6f0a40]
bar([res.MAE; res.RMSE]'); %[output:2e6f0a40]
set(gca, 'XTickLabel', metodos(:,1), 'TickLabelInterpreter', 'none'); %[output:2e6f0a40]
legend('MAE', 'RMSE', 'Location', 'northwest'); %[output:2e6f0a40]
ylabel('Error (m)'); title('Comparacion de errores'); grid on; %[output:2e6f0a40]

%%\ ===================== 6) GRAFICAS: MAPAS DE ERROR =====================
figure('Name', 'Mapas de error', 'Position', [50 50 1400 420]); %[output:075edcd5]
emax = 0;
for m = 1:nM
    emax = max(emax, max(abs(pred{m}(:) - Z(:))));
end
for m = 1:nM %[output:group:84797338]
    subplot(1, nM, m); %[output:075edcd5]
    imagesc(x, y, abs(pred{m} - Z)); axis xy equal tight;
    colormap(gca, parula); caxis([0 emax]); colorbar;
    title(sprintf('Error absoluto: %s (m)', metodos{m,1}));
    xlabel('x'); ylabel('y');
end %[output:group:84797338]

%%\ ===================== FUNCIONES LOCALES =====================

function [x, y, Z] = cargarTerreno(fuente, archivo, nMax)
% Devuelve ejes x, y (en unidades de indice de celda) y la matriz Z (ny x nx).
    switch lower(fuente)
        case 'sintetico'
            n = 101;
            s = linspace(0, 1, n);
            [Xs, Ys] = meshgrid(s, s);
            Z = franke(Xs, Ys);
            Z = 500 * (Z - min(Z(:))) / (max(Z(:)) - min(Z(:)));   % a metros: 0 a 500
        case 'dem'
            [~, ~, ext] = fileparts(archivo);
            if strcmpi(ext, '.asc')
                Z = readmatrix(archivo, 'FileType', 'text', 'NumHeaderLines', 6);
                Z = flipud(Z);                       % el .asc va de norte a sur
            else
                Z = double(imread(archivo));         % GeoTIFF simple
            end
            Z(Z < -1000) = NaN;                      % valores "sin dato"
            Z = Z(1:min(end, nMax), 1:min(end, nMax));
            if any(isnan(Z(:)))
                warning('El DEM tiene %d valores sin dato; se rellenan con la media.', nnz(isnan(Z)));
                Z(isnan(Z)) = mean(Z(~isnan(Z)));
            end
        otherwise
            error('fuente debe ser ''sintetico'' o ''dem''.');
    end
    [ny, nx] = size(Z);
    x = 1:nx;
    y = 1:ny;
end

function f = franke(x, y)
    f = 0.75*exp(-((9*x-2).^2 + (9*y-2).^2)/4) ...
      + 0.75*exp(-((9*x+1).^2)/49 - (9*y+1)/10) ...
      + 0.50*exp(-((9*x-7).^2 + (9*y-3).^2)/4) ...
      - 0.20*exp(-(9*x-4).^2 - (9*y-7).^2);
end

function Zq = interpBilineal(xc, yc, Zc, xq, yq)
% Interpolacion bilineal desde cero (ecuacion (6) del anexo A.5).
% Malla gruesa regular (xc, yc, Zc) evaluada en la malla definida por xq, yq.
    [Xq, Yq] = meshgrid(xq, yq);
    hx = xc(2) - xc(1);
    hy = yc(2) - yc(1);
    nxc = numel(xc);  nyc = numel(yc);

    i = min(max(floor((Xq - xc(1))/hx) + 1, 1), nxc - 1);   % celda en x
    j = min(max(floor((Yq - yc(1))/hy) + 1, 1), nyc - 1);   % celda en y

    s = (Xq - xc(i)) / hx;
    t = (Yq - yc(j)) / hy;

    z00 = Zc(sub2ind(size(Zc), j,   i  ));
    z10 = Zc(sub2ind(size(Zc), j,   i+1));
    z01 = Zc(sub2ind(size(Zc), j+1, i  ));
    z11 = Zc(sub2ind(size(Zc), j+1, i+1));

    Zq = (1-s).*(1-t).*z00 + s.*(1-t).*z10 + (1-s).*t.*z01 + s.*t.*z11;
end

function Zq = interpLagrangeLocal(xc, yc, Zc, xq, yq, p)
% Interpolacion polinomial local por producto tensorial (grado p en cada direccion).
% Ip,p(x,y) = sum_i sum_j z_ij * l_i(x) * m_j(y), con p+1 nodos vecinos.
% Al ser producto tensorial, se calcula como  Zq = Wy * Zc * Wx'.
    Wx = pesosLagrange1D(xc, xq, p);
    Wy = pesosLagrange1D(yc, yq, p);
    Zq = Wy * Zc * Wx';
end

function W = pesosLagrange1D(xn, xq, p)
% Matriz de pesos W (numel(xq) x numel(xn)) tal que u(xq) = W * u(xn),
% usando polinomios de Lagrange de grado p sobre los p+1 nodos mas cercanos.
    xn = xn(:)';  xq = xq(:);
    n = numel(xn);  m = numel(xq);
    if n < p + 1
        error(['La malla gruesa tiene solo %d nodos en una direccion; ' ...
            'Lagrange de grado %d necesita al menos %d. ' ...
            'Reduzcan k o usen un DEM mas grande.'], n, p, p+1);
    end
    h = xn(2) - xn(1);
    W = zeros(m, n);
    for q = 1:m
        i = min(max(floor((xq(q) - xn(1))/h) + 1, 1), n - 1);   % celda [xn(i), xn(i+1)]
        a = i - floor((p-1)/2);                                  % ventana centrada
        a = min(max(a, 1), n - p);                               % sin salirse de la malla
        idx = a:a+p;
        for jj = idx
            otros = idx(idx ~= jj);
            W(q, jj) = prod((xq(q) - xn(otros)) ./ (xn(jj) - xn(otros)));
        end
    end
end

function m = metricas(Zr, Zp, mascara)
% Metricas sobre los puntos quitados (mascara = true).
    e  = Zp(mascara) - Zr(mascara);
    zr = Zr(mascara);
    m.MAE  = mean(abs(e));
    m.RMSE = sqrt(mean(e.^2));
    m.Emax = max(abs(e));
    m.R2   = 1 - sum(e.^2) / sum((zr - mean(zr)).^2);
    m.t    = 0;
end

function mostrarSuperficie(X, Y, Z, titulo, cmap, zl)
    surf(X, Y, Z, 'EdgeColor', 'none');
    colormap(gca, cmap); caxis(zl);
    axis tight; view(35, 45);
    title(titulo);
    xlabel('x'); ylabel('y'); zlabel('Elevacion (m)');
end

function c = terrain_like()
    c = [0.2 0.5 0.2; 0.6 0.7 0.3; 0.8 0.7 0.4; 0.6 0.5 0.4; 1 1 1];
    c = interp1(linspace(0,1,5), c, linspace(0,1,256));
end

